// Monta a mensagem do fim do dia (HTML do Telegram): agenda do próximo dia útil, e-mails críticos sem resposta,
// tarefas abertas do ambiente de trabalho e pedidos atrasados. Uma parte que falhar vira um aviso curto, sem derrubar
// o resto.
const cfg = $('Configuração do fim do dia').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corta = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const resposta = (no) => {
  try {
    return $(no).first()?.json ?? {};
  } catch (e) {
    return { error: { message: 'não rodou' } };
  }
};
const falhou = (r) => Boolean(r.error);
const motivo = (r) => corta(r.error?.message ?? r.error?.description ?? (typeof r.error === 'string' ? r.error : ''), 120);
const avisos = [];
const MAX = Math.min(Math.max(Number(cfg.max_itens) || 8, 1), 15);
const lista = (itens, linha) => itens.slice(0, MAX).map(linha).join('\n') + (itens.length > MAX ? `\n…e mais ${itens.length - MAX}` : '');

// Agenda do próximo dia útil (o Outlook devolve o horário já no fuso do Brasil).
const agenda = resposta('Agenda do próximo dia útil');
const eventos = falhou(agenda) ? [] : (agenda.value ?? []).filter((e) => e && !e.isCancelled);
if (falhou(agenda)) avisos.push(`agenda (${motivo(agenda)})`);
const hora = (dt) => String(dt ?? '').slice(11, 16);
const dataCurta = (iso) => `${iso.slice(8, 10)}/${iso.slice(5, 7)}`;
const alvo = String(cfg.proximo_dia ?? '').slice(0, 10);
// Compromisso de vários dias (férias, viagem...) aparece como "dia todo (até dd/mm)", sem um horário que confunda.
const ultimoDia = (e) => {
  const fim = String(e.end?.dateTime ?? '');
  if (!e.isAllDay && fim.slice(11, 16) !== '00:00') return fim.slice(0, 10);
  const d = new Date(fim.slice(0, 10) + 'T12:00:00Z');
  if (isNaN(d)) return fim.slice(0, 10);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
};
const linhaEvento = (e) => {
  const ultimo = ultimoDia(e);
  const variosDias = Boolean(alvo) && (String(e.start?.dateTime ?? '').slice(0, 10) < alvo || ultimo > alvo);
  const quando =
    e.isAllDay || variosDias ? (alvo && ultimo > alvo ? `dia todo (até ${dataCurta(ultimo)})` : 'dia todo') : `${hora(e.start?.dateTime)}–${hora(e.end?.dateTime)}`;
  const local = e.location?.displayName ? ` (${esc(corta(e.location.displayName, 40))})` : '';
  return `• ${quando} ${esc(corta(e.subject || '(sem assunto)', 70))}${local}`;
};

// E-mails críticos que ele ainda não respondeu (de hoje e dos 2 dias úteis anteriores). Fica de fora o que ele já
// respondeu ou encaminhou (pela marca do Outlook ou por um e-mail dele na mesma conversa, de qualquer aparelho), os
// automáticos, os que o Outlook separou em "Outros" e os em que ele está só em cópia. Sem IA: crítico é o que tem
// alta prioridade, está sinalizado, vem de um remetente importante ou fala de urgência, prazo, problema ou pedido.
const eu = resposta('Quem sou eu');
const meuEmail = String(eu.mail || eu.userPrincipalName || '').trim().toLowerCase();
const emails = resposta('E-mails recebidos');
const enviados = resposta('E-mails enviados');
const criticos = [];
let outrosSemResposta = 0;
const normalizar = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .replace(/\s+/g, ' ')
    .trim();
const listaDaConfig = (s) =>
  String(s ?? '')
    .split(/[,;\n]/)
    .map(normalizar)
    .filter(Boolean);
if (falhou(emails)) avisos.push(`e-mails (${motivo(emails)})`);
else {
  // Conversas em que ele mandou e-mail depois de receber: contam como respondidas.
  const ultimoEnvio = new Map();
  if (falhou(enviados)) avisos.push(`e-mails enviados (${motivo(enviados)})`);
  else
    for (const s of enviados.value ?? []) {
      const conversa = String(s?.conversationId ?? '');
      const quando = String(s?.sentDateTime ?? '');
      if (conversa && quando > (ultimoEnvio.get(conversa) ?? '')) ultimoEnvio.set(conversa, quando);
    }
  // Remetentes automáticos: pelo começo do endereço ou por uma parte do domínio (ex.: avisos@notificacoes.loja.com).
  const AUTOMATICO = /^(no-?reply|nao-?responda|naoresponda|do-?not-?reply|mailer-daemon|postmaster|bounce|notifica|notification|alerta?s?|newsletter|news|marketing|info@|mkt|xml@|nfe@)/;
  const DOMINIO_AUTOMATICO = /@(.+[.-])?(notifica[a-z]*|notifications?|newsletters?|news|mailer|marketing|mkt|bounces?)[.-]/;
  const ASSUNTO_AUTOMATICO = /^(resposta automatica|automatic reply|auto-?reply|out of office|fora do escritorio|ausencia|aceito:|recusado:|provisorio:|accepted:|declined:|tentative:|convite:|invitation:|updated invitation|convite atualizado|cancelado:|canceled:|entrega nao realizada|undeliverable|mail delivery)/;
  const SINAIS = [
    ['urgente', /\b(urgente|urgencia|urgent|emergencia|critic[oa]|imediat[oa]|imediatamente|asap|o quanto antes|com prioridade|prioritari[oa])\b/],
    ['prazo', /\b(atrasad[oa]s?|atraso|vencid[oa]s?|vence hoje|ate hoje|ainda hoje|prazo (final|de hoje|vencido|esgotado)|ultimo aviso|ultima chamada)\b/],
    ['problema', /\b(reclamac(ao|oes)|insatisfeit[oa]s?|multa|cancelamento|parad[oa]|nao funciona|falha grave|devoluc(ao|oes)|juridico|extrajudicial|processo judicial)\b/],
    ['aguarda retorno', /\b(aguardo (o )?(seu|sua) (retorno|resposta|aprovacao)|aguardando (o )?(seu |sua )?(retorno|resposta|aprovacao)|pendente de aprovacao|preciso de (uma )?resposta|favor (retornar|responder)|sem retorno)\b/],
    ['pedido', /\b(pedidos?|trf|transferencias?|cotac(ao|oes)|orcamentos?|solicitac(ao|oes) de compras?|ordens? de compra|ordens? de producao|faturamento|nota fiscal|previsao de entrega|prazo de entrega|status do pedido)\b|\b(op|oc|sc|nf|nfe|nf-e)\s*(n[o°º]?\.?\s*)?:?\s*\d{3,}/],
  ];
  const REMETENTES = listaDaConfig(cfg.remetentes_criticos);
  const PALAVRAS = listaDaConfig(cfg.palavras_criticas);
  const endereco = (r) => String(r?.emailAddress?.address ?? '').trim().toLowerCase();
  for (const m of emails.value ?? []) {
    if (/eventMessage/i.test(String(m['@odata.type'] ?? ''))) continue;
    const de = endereco(m.from) || endereco(m.sender);
    if (!de || (meuEmail && de === meuEmail) || AUTOMATICO.test(de) || DOMINIO_AUTOMATICO.test(de)) continue;
    // Na Caixa de Entrada Destaques, o que o Outlook separou em "Outros" (propaganda, avisos) não conta.
    if (m.inferenceClassification === 'other') continue;
    const assunto = normalizar(m.subject).replace(/^((re|res|fw|fwd|enc|rv|tr)\s*:\s*)+/, '');
    if (ASSUNTO_AUTOMATICO.test(assunto)) continue;
    const verbo = (m.singleValueExtendedProperties ?? []).find((p) => /0x1081/i.test(String(p.id)));
    if (verbo && ['102', '103', '104'].includes(String(verbo.value))) continue;
    if (m.conversationId && (ultimoEnvio.get(String(m.conversationId)) ?? '') > String(m.receivedDateTime ?? '')) continue;
    const para = (m.toRecipients ?? []).map(endereco);
    if (meuEmail && para.length && !para.includes(meuEmail)) continue;

    const texto = `${assunto}\n${normalizar(m.bodyPreview)}`;
    const motivos = [];
    if (m.importance === 'high') motivos.push('alta prioridade');
    if (m.flag?.flagStatus === 'flagged') motivos.push('sinalizado');
    if (REMETENTES.some((r) => (r.includes('@') && !r.startsWith('@') ? de === r : de.endsWith(r.startsWith('@') ? r : '@' + r)))) motivos.push('remetente importante');
    for (const [nome, regra] of SINAIS) if (regra.test(texto)) motivos.push(nome);
    if (PALAVRAS.some((p) => texto.includes(p))) motivos.push('palavra-chave');
    if (motivos.length) criticos.push({ ...m, motivos });
    else outrosSemResposta++;
  }
  // Os com mais sinais primeiro; no empate, quem espera há mais tempo.
  criticos.sort((a, b) => b.motivos.length - a.motivos.length || String(a.receivedDateTime).localeCompare(String(b.receivedDateTime)));
}
const fuso = cfg.fuso_horario || 'America/Sao_Paulo';
const quandoRecebeu = (iso) => {
  const d = new Date(iso);
  if (isNaN(d)) return '';
  const hora = d.toLocaleTimeString('pt-BR', { timeZone: fuso, hour: '2-digit', minute: '2-digit' });
  const dia = new Intl.DateTimeFormat('en-CA', { timeZone: fuso }).format(d);
  return dia === cfg.hoje ? hora : `${dataCurta(dia)} ${hora}`;
};
const linhaEmail = (m) =>
  `• ${quandoRecebeu(m.receivedDateTime)} ${esc(corta(m.from?.emailAddress?.name || m.from?.emailAddress?.address || '', 30))}: ` +
  `${esc(corta(m.subject || '(sem assunto)', 60))} <i>(${esc(m.motivos.join(', '))})</i>`;
const blocoEmails =
  `🚨 <b>E-mails críticos sem resposta: ${falhou(emails) ? '?' : criticos.length}</b>` +
  (falhou(emails) ? '' : criticos.length ? `\n${lista(criticos, linhaEmail)}` : '\nNenhum e-mail crítico esperando você. 👍') +
  (outrosSemResposta ? `\n<i>Outros ${outrosSemResposta} sem resposta não parecem críticos.</i>` : '');

// Tarefas abertas, só do ambiente de trabalho (sem misturar ambientes).
let tarefas = [];
try {
  tarefas = $('Tarefas abertas')
    .all()
    .map((i) => i.json)
    .filter((t) => t && t.titulo);
} catch (e) {
  avisos.push('tarefas');
}
tarefas.sort((a, b) => String(a.prazo || '9999').localeCompare(String(b.prazo || '9999')));
const linhaTarefa = (t) => {
  const prazo = /^\d{4}-\d{2}-\d{2}/.test(String(t.prazo || '')) ? String(t.prazo).slice(0, 10) : '';
  const marca = !prazo ? '' : prazo < cfg.hoje ? ` ⚠️ atrasada (${dataCurta(prazo)})` : prazo === cfg.hoje ? ' (vence hoje)' : ` (até ${dataCurta(prazo)})`;
  return `• ${esc(corta(t.titulo, 70))}${marca}`;
};

// Pedidos atrasados (base oficial de pedidos), em números.
const pedidos = resposta('Pedidos atrasados');
let blocoPedidos = '';
if (falhou(pedidos) || !pedidos.resumo) avisos.push(`pedidos (${motivo(pedidos) || corta(pedidos.erro, 120) || 'sem resposta da base'})`);
else {
  const r = pedidos.resumo;
  const unidades = (r.por_unidade ?? [])
    .slice(0, 4)
    .map((u) => `${esc(corta(u.valor, 25))}: ${u.itens}`)
    .join(' · ');
  blocoPedidos = r.itens
    ? `📦 <b>Pedidos atrasados: ${r.itens} ${r.itens === 1 ? 'item' : 'itens'}</b> em ${r.pedidos} ${r.pedidos === 1 ? 'pedido' : 'pedidos'}` +
      (unidades ? `\n${unidades}` : '')
    : '📦 <b>Pedidos atrasados:</b> nenhum';
  const atualizada = /atualizada em (.+)$/.exec(String(pedidos.fonte ?? ''))?.[1];
  if (atualizada) blocoPedidos += `\n<i>Base de ${esc(atualizada)}</i>`;
}

const partes = [
  `🌙 <b>Fim do dia, ${esc(cfg.nome_dono)}!</b> ${esc(cfg.hoje_extenso)}`,
  `📅 <b>${esc(cfg.proximo_dia_rotulo)}</b>\n` + (falhou(agenda) ? 'Não consegui ler a agenda.' : eventos.length ? lista(eventos, linhaEvento) : 'Nada na agenda.'),
  blocoEmails,
  `✅ <b>Tarefas abertas (${esc(cfg.ambiente_nome)}): ${tarefas.length}</b>` + (tarefas.length ? `\n${lista(tarefas, linhaTarefa)}` : ''),
  blocoPedidos,
  avisos.length ? `⚠️ <i>Não consegui ler: ${esc(avisos.join('; '))}.</i>` : '',
  'Bom descanso! 😊',
].filter(Boolean);
const html = partes.join('\n\n');
return [
  {
    json: {
      html,
      texto_simples: html.replace(/<[^>]+>/g, ''),
      contagens: {
        eventos: eventos.length,
        emails_criticos: falhou(emails) ? null : criticos.length,
        emails_sem_resposta: falhou(emails) ? null : criticos.length + outrosSemResposta,
        tarefas: tarefas.length,
        pedidos_atrasados: pedidos?.resumo?.itens ?? null,
      },
      avisos,
    },
  },
];
